import{_ as t,o,c as d,ag as n}from"./chunks/framework.BZohXCq9.js";const g=JSON.parse('{"title":"Delivery Plan Verification – Phase 1 & Phase 2","description":"","frontmatter":{},"headers":[],"relativePath":"DELIVERY_PLAN_VERIFICATION.md","filePath":"DELIVERY_PLAN_VERIFICATION.md"}'),r={name:"DELIVERY_PLAN_VERIFICATION.md"};function s(a,e,c,i,l,u){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="delivery-plan-verification-–-phase-1-phase-2" tabindex="-1">Delivery Plan Verification – Phase 1 &amp; Phase 2 <a class="header-anchor" href="#delivery-plan-verification-–-phase-1-phase-2" aria-label="Permalink to &quot;Delivery Plan Verification – Phase 1 &amp; Phase 2&quot;">​</a></h1><p>This document verifies each item from your <strong>Revised Delivery Plan</strong> against the current codebase. Each line is marked as <strong>Done</strong>, <strong>Partial</strong>, or <strong>Not found</strong>, with file references.</p><hr><h2 id="phase-1-–-booking-logic-core-payment-foundation" tabindex="-1">Phase 1 – Booking Logic + Core Payment Foundation <a class="header-anchor" href="#phase-1-–-booking-logic-core-payment-foundation" aria-label="Permalink to &quot;Phase 1 – Booking Logic + Core Payment Foundation&quot;">​</a></h2><h3 id="a-booking-status-logic-fix" tabindex="-1">A. Booking Status Logic Fix <a class="header-anchor" href="#a-booking-status-logic-fix" aria-label="Permalink to &quot;A. Booking Status Logic Fix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Status</th><th>Evidence</th></tr></thead><tbody><tr><td>Improve lesson status logic after booking</td><td><strong>Done</strong></td><td>Slot-level <code>lessonStatus</code> and availability status are updated on create/update/cancel. <code>server/src/models/StudentBooking.js</code> (lessonStatus: <code>upcoming</code>, <code>completed</code>, <code>missed</code>, <code>cancelled</code>); <code>server/src/models/teacherAvailability.model.js</code> (status: <code>available</code>, <code>booked</code>, <code>cancelled</code>, <code>missed</code>, <code>completed</code>, <code>refund</code>).</td></tr><tr><td>Reliable transitions: scheduled → completed → missing → cancelled</td><td><strong>Done</strong></td><td>Transitions implemented in <code>studentBooking.resolver.js</code> (<code>updateSlotStatus</code>) and <code>AdminBookingType.resolver.js</code> (<code>updateBookingSlotStatus</code>). Slot status: <code>booked</code>/<code>upcoming</code> → <code>completed</code> or <code>missed</code> or <code>cancelled</code>. Booking status derived from slot counts: all cancelled → <code>cancelled</code>, all completed → <code>completed</code>, mixed → <code>semi_cancelled</code>/<code>confirmed</code>.</td></tr><tr><td>“scheduled” / “missing” naming</td><td><strong>Partial</strong></td><td>Logic matches; naming differs: <strong>scheduled</strong> = <code>booked</code> / <code>upcoming</code>, <strong>missing</strong> = <code>missed</code>. Same behavior.</td></tr><tr><td>Payment and payout logic can safely depend on lesson status</td><td><strong>Done</strong></td><td>Payout job filters by <code>paymentStatus: &quot;paid&quot;</code>, <code>payoutStatus: &quot;pending&quot;</code>, <code>payoutEligibleAt</code>; completion sets <code>payoutStatus: &quot;pending&quot;</code> and <code>payoutEligibleAt</code>. Refund checks <code>slot.status === &quot;cancelled&quot;</code>, no refund if <code>slot.payoutId</code> set. <code>server/src/jobs/payoutJob.js</code>, <code>server/src/graphql/resolvers/refundRequest.resolver.js</code>, <code>server/src/graphql/resolvers/studentBooking.resolver.js</code> (updateSlotStatus).</td></tr></tbody></table><p><strong>Phase 1A verdict:</strong> <strong>Done</strong> (with naming note: scheduled = booked/upcoming, missing = missed).</p><hr><h3 id="b-stripe-core-cards-only" tabindex="-1">B. Stripe Core (Cards Only) <a class="header-anchor" href="#b-stripe-core-cards-only" aria-label="Permalink to &quot;B. Stripe Core (Cards Only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Status</th><th>Evidence</th></tr></thead><tbody><tr><td>Stripe account setup &amp; configuration</td><td><strong>Done</strong></td><td>Express Connect accounts (CH), manual payouts, account links. <code>server/src/services/stripeService.js</code> (<code>createExpressAccount</code>, <code>setManualPayoutSchedule</code>, <code>createAccountLink</code>); <code>server/src/graphql/resolvers.js</code> (createStripeAccount, verifyStripeOnboarding, regenerateStripeLink).</td></tr><tr><td>SetupIntent flow (save card at booking, no charge)</td><td><strong>Done</strong></td><td>Checkout in <code>mode: &quot;setup&quot;</code> when lesson &gt;48h away; only card saved. <code>stripeService.js</code> <code>createCheckoutSessionForBooking</code> with <code>mode: &quot;setup&quot;</code>, <code>setup_intent_data</code>; <code>studentBooking.resolver.js</code> uses <code>isDeferred</code> and passes <code>mode: &quot;setup&quot;</code>; webhook <code>checkout.session.completed</code> and <code>completeDeferredBookingFromCheckout</code> save <code>stripeCustomerId</code> and <code>paymentMethod.paymentMethodId</code>.</td></tr><tr><td>PaymentIntent logic for future charge</td><td><strong>Done</strong></td><td>T-48 job creates and confirms PaymentIntent with saved PM and <code>offSession: true</code>. <code>stripeService.js</code> <code>createPaymentIntentForBooking</code>; <code>t48ChargeJob.js</code> calls it with <code>paymentMethodId</code>, <code>customerId</code>, <code>transferData</code>; webhook <code>payment_intent.succeeded</code> and <code>completeT48SlotPayment</code> mark slot paid and create transactions.</td></tr><tr><td>Destination Charges: DSP commission + instructor share</td><td><strong>Done</strong></td><td>Every charge uses <code>transfer_data.destination</code> and <code>transfer_data.amount</code> (instructor share). Commission split via <code>getCommissionSplit</code>. <code>stripeService.js</code> (createPaymentIntentForBooking, createCheckoutSessionForBooking with <code>payment_intent_data.transfer_data</code>); <code>getCommissionSplit</code> used in studentBooking.resolver, t48ChargeJob, webhook, refundRequest.resolver.</td></tr><tr><td>Stripe webhook: success, failure, payment state sync</td><td><strong>Done</strong></td><td><strong>Success:</strong> <code>checkout.session.completed</code> (setup flow), <code>payment_intent.succeeded</code> (instant + T-48). <strong>Failure / state:</strong> Slot set to <code>payment_failed</code> or <code>requires_action</code> in t48ChargeJob; webhook does not handle <code>payment_intent.payment_failed</code> explicitly but job handles failures. Payment state synced via webhook + resolvers (booking/slot paid, transactions). <code>server/src/routes/stripeWebhook.routes.js</code>.</td></tr><tr><td>Database models: saved payment methods, payment status, instructor earnings ledger</td><td><strong>Done</strong></td><td><strong>Payment methods:</strong> <code>StudentBooking.paymentMethod</code> (paymentMethodId, setupIntentId, cardLast4, cardBrand). <strong>Payment status:</strong> Slot <code>paymentStatus</code> (pending_payment, paid, requires_action, payment_failed, refunded), <code>paymentIntentId</code>, <code>chargedAt</code>, <code>chargeAmount</code>. <strong>Earnings ledger:</strong> <code>Transaction</code> model with type (payment, payout, refund, transfer_reversal), role (platform, instructor, student), amount, stripePaymentIntentId, stripePayoutId, stripeRefundId, etc. <code>server/src/models/StudentBooking.js</code>, <code>server/src/models/transaction.model.js</code>.</td></tr><tr><td>Test-mode validation: successful charge, failed charge, 3DS-required</td><td><strong>Done</strong></td><td>Successful charge: instant flow and T-48 job set slot to paid and create transactions. Failed: T-48 sets <code>payment_failed</code>, retries up to T48_MAX_RETRIES. 3DS: T-48 sets <code>requires_action</code>, stores <code>paymentIntentId</code>, sends <code>payment_requires_action</code> email; frontend <code>getClientSecretForT48SlotPayment</code> + CompletePaymentPage + <code>completeT48SlotPayment</code>. Docs: <code>STRIPE_MANUAL_PAYOUT_TEST.md</code>, <code>TESTING_T48.md</code>, <code>STRIPE_WEBHOOK_LOCAL.md</code>.</td></tr></tbody></table><p><strong>Phase 1B verdict:</strong> <strong>Done.</strong></p><hr><h3 id="phase-1-outcome-checklist" tabindex="-1">Phase 1 Outcome Checklist <a class="header-anchor" href="#phase-1-outcome-checklist" aria-label="Permalink to &quot;Phase 1 Outcome Checklist&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Outcome</th><th>Status</th></tr></thead><tbody><tr><td>Booking logic is payment-safe</td><td><strong>Done</strong> – status transitions and payout/refund guards in place.</td></tr><tr><td>Cards can be saved at booking</td><td><strong>Done</strong> – SetupIntent / setup-mode Checkout when &gt;48h.</td></tr><tr><td>Charges can be executed programmatically</td><td><strong>Done</strong> – PaymentIntent in t48ChargeJob (and instant flow).</td></tr><tr><td>Commission split works correctly</td><td><strong>Done</strong> – getCommissionSplit + transfer_data everywhere.</td></tr><tr><td>Stripe securely holds instructor funds</td><td><strong>Done</strong> – Destination charges to connected account; manual payouts.</td></tr><tr><td>System is production-ready for card payments</td><td><strong>Done</strong> – Webhooks, idempotency, 3DS, refunds, transactions.</td></tr></tbody></table><hr><h2 id="phase-2-–-automation-admin-finalization" tabindex="-1">Phase 2 – Automation, Admin &amp; Finalization <a class="header-anchor" href="#phase-2-–-automation-admin-finalization" aria-label="Permalink to &quot;Phase 2 – Automation, Admin &amp; Finalization&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Status</th><th>Evidence</th></tr></thead><tbody><tr><td>T-48 automated charge scheduler (cron / queue / job)</td><td><strong>Done</strong></td><td><code>runT48ChargeJob</code> invoked on a timer and once at startup. <code>server/src/index.js</code>: <code>T48_JOB_INTERVAL_MS = 5 * 60 * 1000</code>, <code>setInterval(runT48ChargeJob, ...)</code>, plus initial run.</td></tr><tr><td>3DS fallback: email notification</td><td><strong>Done</strong></td><td>On <code>requires_action</code>, t48ChargeJob sends <code>notifyBookingParties(..., &quot;payment_requires_action&quot;)</code>. <code>server/src/jobs/t48ChargeJob.js</code>; <code>server/src/utils/SendOtpEmail.js</code> (<code>payment_requires_action</code>).</td></tr><tr><td>3DS fallback: confirmation / retry flow</td><td><strong>Done</strong></td><td>Student gets client secret via <code>getClientSecretForT48SlotPayment</code>, completes 3DS on CompletePaymentPage, then <code>completeT48SlotPayment</code>. Failed charges retried up to T48_MAX_RETRIES (2 → 3 attempts); then slot marked <code>payment_failed</code>. <code>studentBooking.resolver.js</code>; <code>Frontend/src/pages/private/student-dashboard/CompletePaymentPage.tsx</code>; <code>bookLesson.tsx</code> (Complete payment section).</td></tr><tr><td>Admin-side payment visibility</td><td><strong>Done</strong></td><td>Admin transactions page: <code>getAdminTransactions</code>, <code>getAdminTransactionStats</code>; filter by type (payment, payout, refund, etc.), role, date; transaction list with amount, type, role, description, Stripe IDs. <code>server/src/graphql/resolvers/transaction.resolver.js</code>; <code>Frontend/src/pages/private/admin-dashboard/AdminTransactionsPage.tsx</code>.</td></tr><tr><td>Admin-side instructor payout tracking</td><td><strong>Done</strong></td><td>Slots have <code>payoutStatus</code>, <code>payoutId</code>, <code>payoutDate</code>; payout job sets these. Transactions with type <code>payout</code>, role <code>instructor</code>, <code>stripePayoutId</code>. Admin can see payouts in transaction list and stats. <code>payoutJob.js</code>; <code>transaction.model.js</code>; AdminTransactionsPage (payments/payouts).</td></tr><tr><td>Partial refund logic: DSP commission refunded first, remaining from instructor share</td><td><strong>Done</strong></td><td>Refund flow: (1) <strong>Transfer reversal</strong> for instructor share (<code>createTransferReversal</code>); (2) <strong>Refund</strong> to student for full slot amount (<code>createRefund</code>); (3) <strong>Transactions</strong>: student credit (refund), instructor debit (reversal), platform debit (commission reversal). So DSP commission and instructor share are both reversed; student gets full slot refund. Order in code: reversal first, then refund (Stripe); ledger reflects all three. <code>server/src/graphql/resolvers/refundRequest.resolver.js</code>.</td></tr><tr><td>Final production testing &amp; deployment</td><td><strong>Partial</strong></td><td>Code and flows are in place; no dedicated “production testing” script or deployment checklist in repo. Recommend adding a short production checklist (env vars, webhook URL, first payout timing, etc.) if you want this as a deliverable.</td></tr></tbody></table><p><strong>Phase 2 verdict:</strong> <strong>Done</strong> except “final production testing &amp; deployment,” which is <strong>Partial</strong> (no formal checklist in repo).</p><hr><h3 id="phase-2-outcome-checklist" tabindex="-1">Phase 2 Outcome Checklist <a class="header-anchor" href="#phase-2-outcome-checklist" aria-label="Permalink to &quot;Phase 2 Outcome Checklist&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Outcome</th><th>Status</th></tr></thead><tbody><tr><td>Fully automated charging at T-48</td><td><strong>Done</strong> – T-48 job on interval + idempotency and retries.</td></tr><tr><td>Bank authentication edge cases handled</td><td><strong>Done</strong> – 3DS → requires_action, email, complete-payment flow, retry then payment_failed.</td></tr><tr><td>Admin has full payment visibility</td><td><strong>Done</strong> – AdminTransactionsPage + getAdminTransactionStats.</td></tr><tr><td>Refund logic aligned with DSP rules</td><td><strong>Done</strong> – Student refund + instructor reversal + platform commission reversal.</td></tr><tr><td>Option 1 + booking fix fully completed</td><td><strong>Done</strong> – All Phase 1 and Phase 2 scope above is implemented.</td></tr></tbody></table><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Result</th></tr></thead><tbody><tr><td><strong>Phase 1A – Booking status logic</strong></td><td><strong>Done</strong> (scheduled = booked/upcoming, missing = missed).</td></tr><tr><td><strong>Phase 1B – Stripe core (cards)</strong></td><td><strong>Done</strong>.</td></tr><tr><td><strong>Phase 2 – Automation, admin, refunds</strong></td><td><strong>Done</strong>; “final production testing &amp; deployment” is <strong>Partial</strong> (no in-repo checklist).</td></tr></tbody></table><p><strong>Overall:</strong> The codebase implements all described functionality. The only optional gap is a written production testing/deployment checklist; you can add that under docs or a <code>DEPLOYMENT.md</code> if needed.</p>',25)])])}const h=t(r,[["render",s]]);export{g as __pageData,h as default};
